import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"自然言語のインテリジェントWebクローリングおよびRAG知識構築プラットフォーム | SyncCrawl","description":"自然言語のコマンドでWebデータを収集し、RAG知識ベースを構築します。Web構造の変更に自動的に対応して運用効率を最大化し、LLMのハルシネーションのない正確で信頼性の高い回答を提供する、インテリジェントな統合クローリングソリューションです。","frontmatter":{"title":"自然言語のインテリジェントWebクローリングおよびRAG知識構築プラットフォーム | SyncCrawl","description":"自然言語のコマンドでWebデータを収集し、RAG知識ベースを構築します。Web構造の変更に自動的に対応して運用効率を最大化し、LLMのハルシネーションのない正確で信頼性の高い回答を提供する、インテリジェントな統合クローリングソリューションです。","head":[["meta",{"name":"keywords","content":"Webクローリングソリューション, インテリジェントクローリング, クローリング自動化, 統合クローリングシステム, Webデータ収集, B2B知識ソリューション, リサーチ自動化, RAG (Retrieval-Augmented Generation), RAG知識ベース構築, LLMハルシネーション防止, セマンティック検索, コンテキストベースの質疑応答, AIエージェント, ベクトルストレージ連携, 埋め込み(Embedding)生成, 韓国語最適化, 自然言語コマンドクローリング, 運用効率の最大化, 追加開発作業の最小化, 自動適応システム, 非開発者向けクローリング, 適応型クローリング, 自動化されたセレクタの再学習, 動的Webクローリング, LangChain4j, Playwright MCP, Vector DB, クロスプラットフォームUI, マルチブラウザ対応"}],["meta",{"property":"og:title","content":"自然言語のインテリジェントWebクローリングおよびRAG知識構築プラットフォーム | SyncCrawl"}],["meta",{"property":"og:description","content":"自然言語のコマンドでWebデータを収集し、RAG知識ベースを構築します。Web構造の変更に自動的に対応して運用効率を最大化し、LLMのハルシネーションのない正確で信頼性の高い回答を提供する、インテリジェントな統合クローリングソリューションです。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synccrawl/"}]],"order":1,"dir":{"order":2}},"headers":[],"relativePath":"ja/synccrawl/index.md","filePath":"ja/synccrawl/index.md","lastUpdated":1784367477000}`),a={name:`ja/synccrawl/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<p><strong>SyncCrawl™: 自然言語のインテリジェントクローリングシステム</strong></p><p>SyncCrawl™は、自然言語基盤の統合クローリングシステムであり、インテリジェントなWebコンテンツ収集とRAG（検索拡張生成）基盤の知識構築のための次世代ソリューションです。</p><p>このプラットフォームは、ユーザーの複雑なデータ収集および分析のコマンドを <strong>自然言語で解釈</strong> し、収集されたデータを即座に企業のRAG知識ベースに変換して <strong>信頼性の高い質疑応答システムを構築</strong> するように設計されています。SyncCrawlは単なるクローリングツールを超え、企業の知識資産を構築し活用するインテリジェントな統合プラットフォームを目指しています。</p><hr><h2 id="_1-synccrawlのコア技術スタックと構成" tabindex="-1">1. SyncCrawlのコア技術スタックと構成 <a class="header-anchor" href="#_1-synccrawlのコア技術スタックと構成" aria-label="Permalink to “1. SyncCrawlのコア技術スタックと構成”">​</a></h2><p>SyncCrawlは、Javaベースの先進的なAIフレームワークとWeb自動化ツールを統合して構築されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">区分</th><th style="text-align:left;">内容</th><th style="text-align:left;">出所</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>コアフレームワーク</strong></td><td style="text-align:left;">JavaベースのSpring Bootサーバーアーキテクチャを基盤としています。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>AIレイヤー</strong></td><td style="text-align:left;"><strong>LangChain4j Agent</strong> ベースの自然言語処理とRAGエンジン、Agentシステムを活用します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Web自動化</strong></td><td style="text-align:left;"><strong>Playwright MCP (Model Context Protocol)</strong> Web自動化ツールを統合して使用します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>知識ベース</strong></td><td style="text-align:left;">RAG技術を通じて知識ベースを構築し、ベクトルデータベース(Vector DB)を連携します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>フロントエンド</strong></td><td style="text-align:left;"><strong>Quasar Framework</strong> とElectronを使用してクロスプラットフォームUIをサポートします。</td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="_2-インテリジェントパイプラインアーキテクチャ" tabindex="-1">2. インテリジェントパイプラインアーキテクチャ <a class="header-anchor" href="#_2-インテリジェントパイプラインアーキテクチャ" aria-label="Permalink to “2. インテリジェントパイプラインアーキテクチャ”">​</a></h2><p>SyncCrawlは、クローリングからデータ処理、RAG構築までの全プロセスを自動化するインテリジェントなパイプラインを運用します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">段階</th><th style="text-align:left;">詳細説明</th><th style="text-align:left;">技術要素</th><th style="text-align:left;">出所</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. 自然言語コマンドの解釈</strong></td><td style="text-align:left;">ユーザーの自然言語の要求（例：クローリング、要約）を <strong>LangChain4j Agent</strong> が分析して意図を把握し、Toolの呼び出しを自動化します。</td><td style="text-align:left;">LangChain4j Agent, Tool</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>2. インテリジェントクローリングの実行</strong></td><td style="text-align:left;">Agentが把握した意図に従って、Web自動化Toolである <strong>Playwright MCP</strong> を呼び出します。PlaywrightはChromium、Firefox、WebKitなど複数のブラウザをサポートし、LLMがWebページ要素にアクセスし、相互作用するのを助けます。</td><td style="text-align:left;">Playwright MCP, 動的Web相互作用</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>3. データ収集</strong></td><td style="text-align:left;">Webページと相互作用してHTMLコンテンツを収集します。</td><td style="text-align:left;">Playwright</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>4. データ処理と保存</strong></td><td style="text-align:left;">収集されたHTMLコンテンツをRAGコンポーネントを活用してベクトルデータベースに保存します。</td><td style="text-align:left;">DocumentSplitter, EmbeddingModel, EmbeddingStore</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>5. RAGベースの質疑応答</strong></td><td style="text-align:left;">ユーザーの質問を埋め込み(Embedding)し、<strong>Retriever</strong> が最も類似したドキュメントのChunkを検索します。検索された関連ドキュメントはLLM（例：GPT-4）のプロンプトに「コンテキスト」として注入され、<strong>正確で信頼性の高い回答</strong> が生成されます。</td><td style="text-align:left;">ConversationalRetrievalAgent, LLM</td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="_3-主な機能領域" tabindex="-1">3. 主な機能領域 <a class="header-anchor" href="#_3-主な機能領域" aria-label="Permalink to “3. 主な機能領域”">​</a></h2><p>SyncCrawlは、3つの主要な機能領域を通じて統合的な知識構築環境を提供します。</p><h3 id="i-インテリジェントクローリング機能" tabindex="-1">I. インテリジェントクローリング機能 <a class="header-anchor" href="#i-インテリジェントクローリング機能" aria-label="Permalink to “I. インテリジェントクローリング機能”">​</a></h3><ol><li><strong>自然言語ベースのコマンド処理</strong>: ユーザーの要求の意図を把握し、Toolの呼び出しを自動化します。</li><li><strong>動的Web相互作用</strong>: Playwrightを利用してマルチブラウザサポートとネットワーク制御を提供します。</li><li><strong>適応型クローリング</strong>: ウェブサイトのUI/UXの変更に柔軟に対応し、複雑なサイト（500以上）のクローリングルールを共通化して適用します。これは <strong>自動化されたセレクタの再学習ループ</strong> によって可能になります。</li></ol><h3 id="ii-ragベースの知識構築機能" tabindex="-1">II. RAGベースの知識構築機能 <a class="header-anchor" href="#ii-ragベースの知識構築機能" aria-label="Permalink to “II. RAGベースの知識構築機能”">​</a></h3><ol><li><strong>ドキュメントの分割と埋め込み</strong>: 収集されたコンテンツをDocumentSplitterで意味のあるChunkに分割し、EmbeddingModelを使用して高次元ベクトルに変換します。<strong>韓国語データのためのモデルのサポート</strong> が可能であり、埋め込みの品質を高めることができます。</li><li><strong>ベクトルストレージの連携</strong>: 埋め込まれたデータを永続的に保存し、FAISS、Qdrant、Weaviateなど多様なVector DBへ拡張可能です。</li><li><strong>コンテキストベースの質疑応答</strong>: LLMが保存されたドキュメントを検索し、コンテキストに基づいて正確な回答を生成します。</li></ol><h3 id="iii-システム管理および運用機能" tabindex="-1">III. システム管理および運用機能 <a class="header-anchor" href="#iii-システム管理および運用機能" aria-label="Permalink to “III. システム管理および運用機能”">​</a></h3><ol><li><strong>クローリング設定管理UI</strong>: クローリング対象URL、ルール(CSS Selector)、データ抽出パターン、スケジューリングなどを視覚的に設定できるUIを提供します。</li><li><strong>クロスプラットフォームUI</strong>: Quasar FrameworkとElectronを活用し、単一のコードベースでデスクトップ、Web、モバイルアプリの開発をサポートします。</li><li><strong>リアルタイムモニタリング</strong>: サーバーで進行中のクローリング作業の状態、成功/失敗、データ収集量などを表示するダッシュボードを、Spring REST API連携を通じて提供します。</li><li><strong>対話型設定とメモリ</strong>: NLP意図分析を通じてクローリングルール設定時の対話の意図を分析し、ユーザーごとの対話履歴および相互作用の履歴を管理します（RedisベースのLangChain4j Memoryを活用可能）。</li></ol><hr><h2 id="_4-synccrawlの核心競争力と差別化された価値" tabindex="-1">4. SyncCrawlの核心競争力と差別化された価値 <a class="header-anchor" href="#_4-synccrawlの核心競争力と差別化された価値" aria-label="Permalink to “4. SyncCrawlの核心競争力と差別化された価値”">​</a></h2><p>SyncCrawlは、既存のクローリングシステムが持つ限界を克服し、エンタープライズ環境での知識活用を最大化する差別化された価値を提供します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">競争力要素</th><th style="text-align:left;">SyncCrawlの価値</th><th style="text-align:left;">出所</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>自然言語インターフェース</strong></td><td style="text-align:left;">複雑なコーディングなしに自然言語でクローリングコマンドが可能であり、<strong>非開発者でも簡単に使用</strong> できます。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>自動適応システム</strong></td><td style="text-align:left;">ウェブサイトのUI/UXの変更に自動的に対応し、<strong>保守費用を画期的に削減</strong> し、運用効率を最大化します。500以上の多様なウェブサイトに対応できます。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>正確性と信頼性</strong></td><td style="text-align:left;">LLMのハルシネーションを防ぎ、<strong>実際に収集されたドキュメントに基づく</strong> 信頼できる回答を提供します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>すぐに活用できる知識</strong></td><td style="text-align:left;">収集されたデータが即座に <strong>RAG知識ベースに変換</strong> され、すぐに質疑応答に活用されます。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>韓国語最適化</strong></td><td style="text-align:left;">韓国語コンテンツに対する高品質な埋め込みと検索を実現します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>エンタープライズ級の安定性</strong></td><td style="text-align:left;">Spring Bootベースの堅牢なアーキテクチャとリアルタイムモニタリングにより、安定した運用を保証します。</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>拡張性</strong></td><td style="text-align:left;">多様なVector DBのサポートとクロスプラットフォームUIを通じて、企業の成長に合わせて柔軟に拡張が可能です。</td><td style="text-align:left;"></td></tr></tbody></table>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};